const b64 = bytes => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const unb64 = value => Uint8Array.from(atob(value.replace(/-/g,'+').replace(/_/g,'/') + '='.repeat((4-value.length%4)%4)), c => c.charCodeAt(0));

async function hashPassword(password) {
  if(typeof password !== 'string' || password.length < 10) throw new Error('Password must be at least 10 characters.');
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return argon2id({ password, salt, ...ARGON2_OPTIONS });
}

async function verifyPassword(password, encodedHash) {
  if(typeof password !== 'string' || typeof encodedHash !== 'string' || !encodedHash) return false;
  try { return await argon2Verify({ password, hash: encodedHash }); } catch { return false; }
}

async function creatorSession(creator, secret) {
  const payload = JSON.stringify({ id:creator.id, username:creator.username, role:creator.role, exp:Date.now()+SESSION_MAX_AGE*1000 });
  const encoded = b64(new TextEncoder().encode(payload));
  return encoded + '.' + await sign(secret,payload);
}

async function creatorAuthenticated(request, env) {
  if(!env.CREATOR_SESSION_SECRET) return null;
  const match=(request.headers.get('cookie')||'').match(new RegExp(CREATOR_SESSION_COOKIE + '=([^;]+)'));
  if(!match) return null;
  try {
    const [payload64,signature]=match[1].split('.');
    const payload=new TextDecoder().decode(unb64(payload64));
    if((await sign(env.CREATOR_SESSION_SECRET,payload))!==signature) return null;
    const data=JSON.parse(payload);
    if(!data?.id || !data?.username || data.exp<=Date.now()) return null;
    return data;
  } catch { return null; }
}
async function sign(secret, value) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), {name:'HMAC',hash:'SHA-256'}, false, ['sign']);
  const bytes=new Uint8Array(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(value)));
  return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
}

async function session(username, secret) {
  const payload = username+'|'+(Date.now() + SESSION_MAX_AGE * 1000);
  return b64(new TextEncoder().encode(payload))+'.'+await sign(secret,payload);
}

async function authenticated(request, env) {
  if (!env.ADMIN_SESSION_SECRET) { adminAuthLog('SESSION_VALIDATION_FAILED',{reason:'ADMIN_SESSION_SECRET_MISSING'}); return false; }
  const cookieHeader=request.headers.get('cookie')||'';
  const match=cookieHeader.split(';').map(x=>x.trim()).find(x=>x.startsWith(SESSION_COOKIE+'='));
  if(!match) return false;
  try {
    const token=match.slice(SESSION_COOKIE.length+1);
    const dot=token.indexOf('.');
    if(dot<1) { adminAuthLog('SESSION_VALIDATION_FAILED',{reason:'MALFORMED_SESSION'}); return false; }
    const payload64=token.slice(0,dot); const signature=token.slice(dot+1);
    const payload=new TextDecoder().decode(unb64(payload64));
    const separator=payload.lastIndexOf('|');
    const username=separator>0?payload.slice(0,separator):''; const expiry=separator>0?payload.slice(separator+1):'';
    if(!username||!expiry||Number(expiry)<=Date.now()) { adminAuthLog('SESSION_VALIDATION_FAILED',{reason:'EXPIRED_OR_INVALID_PAYLOAD'}); return false; }
    const expected=await sign(env.ADMIN_SESSION_SECRET,payload);
    if(expected!==signature) { adminAuthLog('SESSION_VALIDATION_FAILED',{reason:'SIGNATURE_MISMATCH'}); return false; }
    const configuredUser=String(env.ADMIN_USERNAME||'').trim();
    if(!configuredUser || username!==configuredUser) { adminAuthLog('SESSION_VALIDATION_FAILED',{reason:'ADMIN_USERNAME_MISMATCH'}); return false; }
    return true;
  } catch { adminAuthLog('SESSION_VALIDATION_FAILED',{reason:'VALIDATION_EXCEPTION'}); return false; }
}

async function adminCanRemoveFraud(request,env) {
  // Existing Worker-secret admin is the trusted administrative boundary for V1.
  return authenticated(request,env);
}

const SUPABASE_DEFAULT_URL = 'https://moczgrwxtfexdbjthxpd.supabase.co';

function supabaseConfig(env){
  const base=String(env.SUPABASE_URL||SUPABASE_DEFAULT_URL).replace(/\/$/,'');
  const key=String(env.SUPABASE_SECRET_KEY||'').trim();
  if(!key) throw new Error('SUPABASE_SECRET_KEY is not configured in the Worker.');
  return {base,key};
}
async function supabaseRest(env,path,options={}){
  const {base,key}=supabaseConfig(env);
  const response=await fetch(base+'/rest/v1/'+path,{
    ...options,
    headers:{
      apikey:key,
      Accept:'application/json',
      ...(options.body?{'content-type':'application/json'}:{}),
      ...(options.headers||{})
    }
  });
  const text=await response.text();
  let body=null;
  try{body=text?JSON.parse(text):null;}catch{throw new Error('Supabase returned invalid JSON.');}
  if(!response.ok){
    const message=body?.message||body?.hint||body?.details||'Supabase request failed ('+response.status+').';
    throw new Error(message);
  }
  return body;
}

async function supabaseAuthUser(env, token) {
  const {base,key}=supabaseConfig(env);
  const response=await fetch(base+'/auth/v1/user',{
    headers:{apikey:key,Authorization:'Bearer '+token,Accept:'application/json'}
  });
  if(!response.ok) return null;
  return await response.json().catch(()=>null);
}

function bearerToken(request) {
  const value=request.headers.get('authorization')||'';
  return /^Bearer\s+(.+)$/i.test(value) ? value.replace(/^Bearer\s+/i,'').trim() : '';
}

async function accountContext(request, env) {
  const token=bearerToken(request);
  if(!token) return null;
  const user=await supabaseAuthUser(env,token);
  if(!user?.id) return null;
  const rows=await supabaseRest(env,
    'accounts?auth_user_id=eq.'+encodeURIComponent(user.id)+
    '&select=id,auth_user_id,username,display_name,avatar_url,state,created_at,updated_at,system_account&limit=1'
  );
  const account=rows?.[0];
  if(!account || account.system_account) return null;
  return {token,user,account};
}

function validateUsername(value) {
  const username=String(value||'').trim().toLowerCase();
  if(!/^[a-z0-9][a-z0-9._-]{1,22}[a-z0-9]$/.test(username)) {
    throw new Error('Username must be 3-24 characters and use lowercase letters, numbers, dots, underscores or hyphens.');
  }
  return username;
}

function validateAvatarUrl(value) {
  const raw=String(value||'').trim();
  if(!raw) return null;
  let url;
  try { url=new URL(raw); } catch { throw new Error('Avatar URL must be a valid URL.'); }
  if(!['http:','https:'].includes(url.protocol)) throw new Error('Avatar URL must use HTTPS or HTTP.');
  return raw.slice(0,2048);
}

async function accountApi(request, env, url) {
  const context=await accountContext(request,env);
  if(!context) return json({error:'Authentication required.'},401);

  const {account,user}=context;
  if(request.method==='GET' && url.pathname==='/api/account/me') {
    const [progress,settings,rewards,activity]=await Promise.all([
      supabaseRest(env,'account_progress?account_id=eq.'+encodeURIComponent(account.id)+'&select=xp_balance,level,current_streak,longest_streak,last_qualifying_activity_at&limit=1'),
      supabaseRest(env,'profile_settings?account_id=eq.'+encodeURIComponent(account.id)+'&select=*&limit=1'),
      supabaseRest(env,'reward_accounts?account_id=eq.'+encodeURIComponent(account.id)+'&select=balance,lifetime_earned,lifetime_spent,lifetime_reversed&limit=1'),
      supabaseRest(env,'activity_events?account_id=eq.'+encodeURIComponent(account.id)+'&select=id,event_type,entity_type,entity_id,created_at&order=created_at.desc&limit=8')
    ]);
    const p=progress?.[0]||{}, st=settings?.[0]||{}, rw=rewards?.[0]||{};
    return json({account:{
      id:account.id,username:account.username,displayName:account.display_name,avatarUrl:account.avatar_url,
      state:account.state,createdAt:account.created_at,updatedAt:account.updated_at,
      email:user.email||null,emailConfirmedAt:user.email_confirmed_at||null,
      level:Number(p.level||1),xp:Number(p.xp_balance||0),currentStreak:Number(p.current_streak||0),
      longestStreak:Number(p.longest_streak||0),tokens:Number(rw.balance||0)
    },settings:st,activity:activity||[]});
  }

  if(request.method==='PUT' && url.pathname==='/api/account/profile') {
    if(['closed','fraud_removed'].includes(account.state)) return json({error:'This account is not available for profile changes.'},403);
    const input=await request.json().catch(()=>({}));
    let username;
    try { username=validateUsername(input.username); } catch(e) { return json({error:e.message},400); }
    let avatarUrl;
    try { avatarUrl=validateAvatarUrl(input.avatarUrl); } catch(e) { return json({error:e.message},400); }
    const displayName=String(input.displayName||'').trim();
    if(displayName.length>80) return json({error:'Display name must be 80 characters or fewer.'},400);
    try {
      const result=await supabaseRest(env,'rpc/server_update_account_profile',{
        method:'POST',
        body:JSON.stringify({
          p_account_id:account.id,
          p_username:username,
          p_display_name:displayName,
          p_avatar_url:avatarUrl
        })
      });
      return json({ok:true,result});
    } catch(error) {
      const msg=String(error?.message||'Unable to save profile.');
      return json({error:/duplicate|taken/i.test(msg)?'That username is already taken.':msg},400);
    }
  }

  if(request.method==='PUT' && url.pathname==='/api/account/settings') {
    const input=await request.json().catch(()=>({}));
    const b=(key)=>Boolean(input?.[key]);
    try {
      const result=await supabaseRest(env,'rpc/server_update_profile_settings',{
        method:'POST',
        body:JSON.stringify({
          p_account_id:account.id,
          p_profile_public:b('profile_public'),
          p_show_display_name:b('show_display_name'),
          p_show_level:b('show_level'),
          p_show_xp:b('show_xp'),
          p_show_streak:b('show_streak'),
          p_show_joined_date:b('show_joined_date'),
          p_show_achievements:b('show_achievements'),
          p_show_tournament_stats:b('show_tournament_stats'),
          p_show_activity_summary:b('show_activity_summary')
        })
      });
      return json({ok:true,result});
    } catch(error) { return json({error:error?.message||'Unable to save privacy settings.'},400); }
  }

  if(request.method==='GET' && url.pathname==='/api/account/activity') {
    const limit=Math.max(1,Math.min(50,Number(url.searchParams.get('limit')||20)));
    const before=String(url.searchParams.get('before')||'').trim();
    let query='activity_events?account_id=eq.'+encodeURIComponent(account.id)+'&select=id,event_type,entity_type,entity_id,metadata,source,created_at&order=created_at.desc&limit='+limit;
    if(before) query+='&created_at=lt.'+encodeURIComponent(before);
    return json({items:await supabaseRest(env,query)});
  }

  if(request.method==='GET' && url.pathname==='/api/account/xp') {
    const limit=Math.max(1,Math.min(50,Number(url.searchParams.get('limit')||25)));
    const rows=await supabaseRest(env,'xp_transactions?account_id=eq.'+encodeURIComponent(account.id)+'&select=id,amount,source_type,source_id,reason,created_at&order=created_at.desc&limit='+limit);
    return json({items:rows});
  }

  if(request.method==='GET' && url.pathname==='/api/account/tokens') {
    const limit=Math.max(1,Math.min(50,Number(url.searchParams.get('limit')||25)));
    const rows=await supabaseRest(env,'reward_ledger?account_id=eq.'+encodeURIComponent(account.id)+'&select=id,entry_type,amount,memo,expires_at,reversal_of_id,created_at&order=created_at.desc&limit='+limit);
    return json({items:rows});
  }

  return null;
}

async function publicProfileApi(request, env, url) {
  if(request.method!=='GET') return json({error:'Method not allowed.'},405);
  const match=url.pathname.match(/^\/api\/public\/profile\/([^/]+)\/?$/);
  if(!match) return null;
  const username=decodeURIComponent(match[1]).trim().toLowerCase();
  if(!/^[a-z0-9][a-z0-9._-]{1,22}[a-z0-9]$/.test(username)) return json({error:'Profile not found.'},404);
  const rows=await supabaseRest(env,
    'profile_public?username=eq.'+encodeURIComponent(username)+
    '&select=username,display_name,avatar_url,level,xp,current_streak,longest_streak,selected_title,joined_at,is_public,show_display_name,show_level,show_xp,show_streak,show_joined_date,show_achievements,show_tournament_stats,show_activity_summary&limit=1'
  );
  const p=rows?.[0];
  if(!p || !p.is_public) return json({error:'This profile does not exist or is private.'},404);
  return json({profile:p},200,{'cache-control':'public, max-age=60, stale-while-revalidate=300'});
}

function editorialStatus(value){
  return ({draft:'draft',review:'in_review',in_review:'in_review',changes_requested:'changes_requested',published:'published',scheduled:'scheduled',approved:'approved',archived:'archived',trash:'trash'})[String(value||'draft')]||'draft';
}
function editorialUiStatus(value){
  return ({in_review:'review',changes_requested:'review',approved:'published'})[String(value||'draft')]||String(value||'draft');
}
function editorialRow(row){
  const tags=Array.isArray(row.tags)?row.tags:[];
  return {
    id:row.id,
    body:row.content_html||'',
    data:{
      id:row.id,slug:row.slug,title:row.title,subtitle:row.subtitle||'',
      description:row.description||row.excerpt||'',excerpt:row.excerpt||row.description||'',
      content:row.content_html||'',contentJson:row.content_json||null,
      type:row.type||'guide',category:row.category||'Guides',author:row.author_name||'TanzimFC',
      authorSlug:row.author_slug||'',status:editorialUiStatus(row.status),image:row.cover_image||'',
      imageAlt:row.image_alt||'',imageCaption:row.image_caption||'',thumbnail:row.cover_image||'',
      featured:Boolean(row.featured),readingTime:Number(row.reading_time||1),tags,
      seoTitle:row.seo_title||'',seoDescription:row.seo_description||'',canonicalUrl:row.canonical_url||'',
      factStatus:row.fact_status||'verified',lastReviewed:row.last_reviewed||'',sources:Array.isArray(row.sources)?row.sources:[],
      relatedArticles:Array.isArray(row.related_articles)?row.related_articles:[],relatedTools:Array.isArray(row.related_tools)?row.related_tools:[],
      series:row.series||'',seriesOrder:row.series_order??null,createdAt:row.created_at,updatedAt:row.updated_at,publishedAt:row.published_at||null
    }
  };
}
async function editorialRevision(env,articleId,input,actorName='TanzimFC'){
  const existing=await supabaseRest(env,"article_revisions?select=revision_no&article_id=eq."+encodeURIComponent(articleId)+"&order=revision_no.desc&limit=1");
  const revisionNo=Number(existing?.[0]?.revision_no||0)+1;
  const article=(await supabaseRest(env,"articles?id=eq."+encodeURIComponent(articleId)+"&select=content_json,content_html,slug,title,subtitle,excerpt,description,cover_image,image_alt,image_caption,featured,seo_title,seo_description,canonical_url,series,tags,reading_time&limit=1"))?.[0];
  if(!article) return;
  await supabaseRest(env,'article_revisions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify([{
    article_id:Number(articleId),revision_no:revisionNo,editor_id:null,editor_name:actorName,
    action:input.action||'save',note:String(input.note||''),content_json:article.content_json||{},
    content_html:article.content_html||'',metadata:{title:article.title,subtitle:article.subtitle,slug:article.slug,tags:article.tags||[],featured:Boolean(article.featured)}
  }])});
  return revisionNo;
}
async function editorialIdentity(request,env){
  if(await authenticated(request,env)){
    return {role:'admin',name:String(env.ADMIN_DISPLAY_NAME||env.ADMIN_USERNAME||'TanzimFC'),ownerKey:'admin'};
  }
  const creator=await creatorRecord(request,env);
  if(!creator) return null;
  return {role:'writer',name:String(creator.display_name||creator.username||'Writer'),ownerKey:'creator:'+String(creator.id),creator};
}

async function editorialArticles(env,identity){
  let path="articles?select=*&order=updated_at.desc&limit=100";
  if(identity?.role==='writer') path+="&owner_key=eq."+encodeURIComponent(identity.ownerKey);
  const rows=await supabaseRest(env,path);
  return (rows||[]).map(row=>{
    const mapped=editorialRow({...row,category_name:row.category});
    return mapped;
  });
}

async function editorialInbox(env,identity){
  if(identity?.role==='admin'){
    const reviews=await supabaseRest(env,"article_reviews?select=*,articles(id,title,slug,author_name,status)&status=eq.submitted&order=created_at.asc&limit=100");
    const items=[];
    for(const review of reviews||[]){
      const revisions=await supabaseRest(env,"article_revisions?select=revision_no,note,created_at&article_id=eq."+encodeURIComponent(review.article_id)+"&order=revision_no.desc&limit=1");
      items.push({
        id:review.id,article_id:review.article_id,revision_no:revisions?.[0]?.revision_no||1,note:review.comment||'',
        created_at:review.created_at,title:review.articles?.title||'Untitled',slug:review.articles?.slug||'',
        status:review.articles?.status||'in_review',author_name:review.articles?.author_name||'Writer'
      });
    }
    return items;
  }
  const rows=await supabaseRest(env,"editorial_inbox?recipient_key=eq."+encodeURIComponent(identity.ownerKey)+"&order=created_at.desc&limit=100");
  return rows||[];
}

async function creatorEditorialRoute(request,env,path){
  if(path==='/me' && request.method==='GET'){
    const creator=await creatorRecord(request,env);
    if(!creator) return json({error:'Authentication required.'},401);
    return json({creator:{id:creator.id,username:creator.username,displayName:creator.display_name,role:creator.role}});
  }
  if(path==='/logout' && request.method==='POST'){
    return json({ok:true},200,{'set-cookie':CREATOR_SESSION_COOKIE+'=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict'});
  }
  return null;
}

async function editorialApi(request,env,path){
  try{
  const identity=await editorialIdentity(request,env);
  if(!identity) return json({error:'Unauthorized.'},401);

  if(path==='/articles' && request.method==='GET') return json({articles:await editorialArticles(env,identity)});
  if(path==='/articles/trash' && request.method==='GET'){
    if(identity.role!=='admin') return json({articles:[]});
    const rows=await supabaseRest(env,'articles?status=eq.trash&order=updated_at.desc&limit=100');
    return json({articles:(rows||[]).map(row=>editorialRow({...row,category_name:row.category}))});
  }
  if(path==='/inbox' && request.method==='GET') return json({items:await editorialInbox(env,identity)});

  const revisionsMatch=path.match(/^\/articles\/(\d+)\/revisions$/);
  if(revisionsMatch && request.method==='GET'){
    const id=revisionsMatch[1];
    const rows=await supabaseRest(env,"article_revisions?article_id=eq."+id+"&select=*&order=revision_no.desc");
    if(identity.role==='writer'){
      const own=await supabaseRest(env,"articles?id=eq."+id+"&owner_key=eq."+encodeURIComponent(identity.ownerKey)+"&select=id&limit=1");
      if(!own?.length) return json({error:'Article not found.'},404);
    }
    const normalized=(rows||[]).map(row=>({
      ...row,
      editor_role:row.editor_role||'editorial',
      review_status:row.review_status||row.action||'save',
      snapshot:JSON.stringify({content:row.content_html||'',metadata:row.metadata||{},contentJson:row.content_json||{}})
    }));
    return json({revisions:normalized});
  }

  const actionMatch=path.match(/^\/articles\/(\d+)\/(approve|request-changes)$/);
  if(actionMatch && request.method==='POST'){
    if(identity.role!=='admin') return json({error:'Only editors can approve or request changes.'},403);
    const id=actionMatch[1],action=actionMatch[2];
    const body=await request.json().catch(()=>({})),note=String(body.note||'').trim();
    const article=(await supabaseRest(env,"articles?id=eq."+id+"&select=id,title,slug,author_name,status,owner_key,published_at&limit=1"))?.[0];
    if(!article) return json({error:'Article not found.'},404);

    const next=action==='approve'?'published':'changes_requested';
    const update={status:next,updated_at:new Date().toISOString()};
    if(action==='approve') update.published_at=article.published_at||new Date().toISOString();
    await supabaseRest(env,"articles?id=eq."+id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(update)});
    const submitted=await supabaseRest(env,"article_reviews?article_id=eq."+id+"&status=eq.submitted&select=id&order=created_at.desc&limit=1");
    const reviewPayload={status:action==='approve'?'approved':'changes_requested',comment:note,reviewer_name:identity.name};
    if(submitted?.[0]?.id){
      await supabaseRest(env,"article_reviews?id=eq."+submitted[0].id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(reviewPayload)});
    }else{
      await supabaseRest(env,'article_reviews',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify([{article_id:Number(id),reviewer_id:null,...reviewPayload}])});
    }
    await editorialRevision(env,Number(id),{action:action==='approve'?'approve':'request_changes',note},identity.name);

    if(action==='approve'){
      await supabaseRest(env,'editorial_inbox',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify([{
        recipient_id:null,recipient_key:article.owner_key||null,actor_id:null,article_id:Number(id),
        kind:'published',title:'Article published',message:'Your article has been approved and published.'
      }])});
    }else{
      await supabaseRest(env,'editorial_inbox',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify([{
        recipient_id:null,recipient_key:article.owner_key||null,actor_id:null,article_id:Number(id),
        kind:'changes_requested',title:'Changes requested',message:note
      }])});
    }
    return json({ok:true,action:action==='approve'?'approved':'changes_requested'});
  }

  const trashMatch=path.match(/^\/articles\/(\d+)\/(trash|restore)$/);
  if(trashMatch && request.method==='POST'){
    if(identity.role!=='admin') return json({error:'Only editors can manage article trash.'},403);
    const id=trashMatch[1],action=trashMatch[2];
    await supabaseRest(env,"articles?id=eq."+id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({
      status:action==='trash'?'trash':'draft',updated_at:new Date().toISOString()
    })});
    return json({ok:true,action});
  }

  if(path==='/inbox/read' && request.method==='POST'){
    const body=await request.json().catch(()=>({}));
    const id=Number(body.id);
    if(!Number.isInteger(id)||id<1) return json({error:'Invalid inbox item.'},400);
    const readFilter=identity.role==='writer'?"&recipient_key=eq."+encodeURIComponent(identity.ownerKey):'';
    await supabaseRest(env,"editorial_inbox?id=eq."+id+readFilter,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({read_at:new Date().toISOString()})});
    return json({ok:true});
  }

  const articleUpdateMatch=path.match(/^\/articles\/(\d+)$/);
  if((path==='/articles' && request.method==='POST') || (articleUpdateMatch && (request.method==='PUT'||request.method==='PATCH'))){
    const input=await request.json().catch(()=>({}));
    if(articleUpdateMatch) input.id=Number(articleUpdateMatch[1]);
    const title=String(input.title||'').trim();
    const slug=String(input.slug||title).trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,160);
    if(!title||!slug) return json({error:'Article title is required.'},400);
    const isAutosave=Boolean(input.autosave);
    let status=editorialStatus(input.status);
    if(identity.role==='writer' && status==='published') status='in_review';

    const bySlug=await supabaseRest(env,"articles?slug=eq."+encodeURIComponent(slug)+"&select=id,owner_key,status&limit=1");
    const existingId=input.id?Number(input.id):(bySlug?.[0]?.id||null);
    let existing=null;
    if(existingId){
      existing=(await supabaseRest(env,"articles?id=eq."+existingId+"&select=*&limit=1"))?.[0]||null;
      if(!existing) return json({error:'Article not found.'},404);
      if(identity.role==='writer' && existing.owner_key!==identity.ownerKey) return json({error:'You can only edit your own articles.'},403);
      if(identity.role==='writer' && !['draft','changes_requested','in_review'].includes(existing.status)) return json({error:'This article is locked after publication.'},409);
    }else if(bySlug?.length && identity.role==='writer' && bySlug[0].owner_key!==identity.ownerKey){
      return json({error:'An article with this slug already exists.'},409);
    }

    const payload={
      slug,title,subtitle:String(input.subtitle||''),excerpt:String(input.description||input.excerpt||''),
      description:String(input.description||input.excerpt||''),content_html:String(input.bodyHtml||input.body||''),
      content_json:input.contentJson&&typeof input.contentJson==='object'?input.contentJson:{},
      author_name:identity.role==='writer'?identity.name:String(input.author||identity.name||'TanzimFC'),
      author_slug:String(input.authorSlug||identity.name||'TanzimFC').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),
      status,owner_key:existing?.owner_key||identity.ownerKey,author_key:existing?.author_key||identity.ownerKey,
      cover_image:String(input.image||''),image_alt:String(input.imageAlt||''),image_caption:String(input.imageCaption||''),
      featured:identity.role==='admin'?Boolean(input.featured):Boolean(existing?.featured),
      type:String(input.type||existing?.type||'guide'),category:String(input.category||existing?.category||'Guides'),
      tags:Array.isArray(input.tags)?input.tags:(existing?.tags||[]),
      seo_title:String(input.seoTitle||title),seo_description:String(input.seoDescription||input.description||''),
      canonical_url:String(input.canonicalUrl||existing?.canonical_url||''),
      fact_status:String(input.factStatus||existing?.fact_status||'verified'),last_reviewed:input.lastReviewed?String(input.lastReviewed):(existing?.last_reviewed||null),
      sources:Array.isArray(input.sources)?input.sources:(existing?.sources||[]),
      related_articles:Array.isArray(input.relatedArticles)?input.relatedArticles:(existing?.related_articles||[]),
      related_tools:Array.isArray(input.relatedTools)?input.relatedTools:(existing?.related_tools||[]),
      series:String(input.series||existing?.series||''),series_order:Number.isFinite(Number(input.seriesOrder))?Number(input.seriesOrder):existing?.series_order||null,
      reading_time:Number(input.readingTime||existing?.reading_time||1),
      published_at:status==='published'?(existing?.published_at||new Date().toISOString()):null,
      updated_at:new Date().toISOString()
    };

    let saved;
    if(existingId) saved=await supabaseRest(env,"articles?id=eq."+existingId,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(payload)});
    else saved=await supabaseRest(env,'articles',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify([payload])});

    const savedRow=saved?.[0];
    if(!savedRow) return json({error:'Article could not be saved.'},500);
    const revisionNo=await editorialRevision(env,savedRow.id,{
      action:status==='published'?'publish':status==='in_review'?'submit':'save'
    },identity.name);

    if(status==='in_review'){
      const pending=await supabaseRest(env,"article_reviews?article_id=eq."+encodeURIComponent(savedRow.id)+"&status=eq.submitted&select=id&limit=1");
      if(!pending?.length){
        await supabaseRest(env,'article_reviews',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify([{
          article_id:savedRow.id,reviewer_id:null,reviewer_name:'',status:'submitted',comment:''
        }])});
      }
    }
    return json({
      ok:true,
      articleId:savedRow.id,
      slug:savedRow.slug,
      action:existingId?'updated':'created',
      revisionNo,
      status:editorialUiStatus(savedRow.status),
      updatedAt:savedRow.updated_at,
      contentLength:String(savedRow.content_html||'').length
    });
  }

  return json({error:'Editorial endpoint not found.'},404);
  }catch(error){
    return json({error:error?.message||'Editorial backend failed.'},500);
  }
}


async function github(env, path, options = {}) {
  const [owner, repo] = (env.GITHUB_REPO || 'TanzimFC/fcmobiletools').split('/');
  if (!env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not configured in the Worker.');
  const response = await fetch(`https://api.github.com/repos/${owner}/${repo}/${path}`, {
    ...options,
    headers: { accept:'application/vnd.github+json', authorization:`Bearer ${env.GITHUB_TOKEN}`, 'x-github-api-version':'2022-11-28', 'user-agent':'FC-Mobile-Tools-Admin', ...(options.headers || {}) }
  });
  const text = await response.text();
  let body = null;
  try { body = text ? JSON.parse(text) : null; } catch { throw new Error('GitHub returned an invalid JSON response.'); }
  if (!response.ok) throw new Error(body?.message || `GitHub request failed (${response.status}).`);
  return body;
}

function decodeGithub(value) { return new TextDecoder().decode(Uint8Array.from(atob(value.replace(/\s/g,'')), c=>c.charCodeAt(0))); }
function encodeGithub(value) { return btoa(String.fromCharCode(...new TextEncoder().encode(value))); }

async function repoFile(env,path) {
  const body = await github(env,`contents/${path}?ref=main`);
  return {sha:body.sha,text:decodeGithub(body.content)};
}

async function writeRepoFile(env,path,text,sha,message) {
  const body = await github(env,`contents/${path}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({message,content:encodeGithub(text),sha,branch:'main'})});
  return body.commit?.sha;
}

const AD_SETTINGS_BUILD_FIX = '2026-09-26';

function parseSiteAds(text) {
  const match=text.match(/export const SITE_ADS = (\{[\s\S]*?\});\s*$/);
  if(!match) throw new Error('Ad configuration file has an unexpected format.');
  try { return JSON.parse(match[1]); } catch { throw new Error('Ad configuration is not valid JSON.'); }
}

function validateSiteAds(content) {
  if(!content || typeof content!=='object') throw new Error('Ad configuration is required.');
  content.enabled=Boolean(content.enabled);
  content.provider=String(content.provider||'Monetag').trim()||'Monetag';

  if(!content.popunder || typeof content.popunder!=='object') throw new Error('Popunder configuration is missing.');
  if(!content.push || typeof content.push!=='object') throw new Error('Push configuration is missing.');

  content.popunder.enabled=Boolean(content.popunder.enabled);
  content.popunder.zone=String(content.popunder.zone||'').trim();
  content.popunder.src=String(content.popunder.src||'').trim();
  content.push.enabled=Boolean(content.push.enabled);
  content.push.zone=String(content.push.zone||'').trim();
  content.push.src=String(content.push.src||'').trim();
  content.push.delayMs=Number(content.push.delayMs);

  const validHttps=(value)=>{try{return new URL(value).protocol==='https:';}catch{return false;}};
  if(!content.popunder.zone || !validHttps(content.popunder.src)) throw new Error('Popunder network settings are invalid.');
  if(!content.push.zone || !validHttps(content.push.src)) throw new Error('Push network settings are invalid.');
  if(!Number.isInteger(content.push.delayMs) || content.push.delayMs<5000 || content.push.delayMs>300000) throw new Error('Push delay must be between 5 and 300 seconds.');

  // Never allow the admin UI to remove the private exclusions.
  content.excludedPathPrefixes=['/admin','/api','/creator/login'];
  return content;
}

function siteAdsText(content) {
  return '// Central ad configuration managed by the FC Mobile Tools admin panel.\n// /admin, /api, and /creator/login remain excluded from ads server-side.\nexport const SITE_ADS = '+JSON.stringify(content,null,2)+';\n';
}



function parseFcMobile27(text) {
  const match=text.match(/export const FC_MOBILE_27 = ([\s\S]+);\s*$/);
  if(!match) throw new Error('FC Mobile 27 data file has an unexpected format.');
  try { return JSON.parse(match[1]); } catch { throw new Error('FC Mobile 27 data file is not JSON-compatible.'); }
}
function validateFcMobile27(content) {
  if(!content || typeof content!=='object' || !Array.isArray(content.releases) || !content.releases.length) throw new Error('At least one FC Mobile 27 release is required.');
  const seen=new Set();
  for(const release of content.releases) {
    if(!release?.id || seen.has(release.id)) throw new Error('Release IDs must be unique and non-empty.');
    seen.add(release.id);
    if(!release.title || !release.version || !release.releaseDate) throw new Error('Release title, version, and release date are required.');
    try {
      const installUrl = new URL(String(release.installUrl||''));
      if(installUrl.protocol !== 'https:' || installUrl.hostname.toLowerCase() !== 'play.google.com') {
        throw new Error('Official install URL must be the Google Play listing.');
      }
    } catch(error) {
      throw new Error(error?.message === 'Official install URL must be the Google Play listing.'
        ? error.message
        : 'Official install URL must be a valid HTTPS Google Play URL.');
    }
    release.installUrl = String(release.installUrl).trim();
    if(!/^\d{4}-\d{2}-\d{2}$/.test(String(release.releaseDate))) throw new Error('Release date must use YYYY-MM-DD.');
    if(!Array.isArray(release.changelog)) release.changelog=[];
    release.changelog=release.changelog.map(x=>String(x).trim()).filter(Boolean);
    release.status=['latest','active','archived'].includes(release.status)?release.status:'archived';
  }
  const latest=content.releases.findIndex(x=>x.status==='latest');
  if(latest<0) content.releases[0].status='latest';
  else content.releases.forEach((x,i)=>{ if(i!==latest && x.status==='latest') x.status='active'; });
  content.lastUpdated=new Date().toISOString().slice(0,10);
}
function fcMobile27Text(content) {
  return '// FC Mobile 27 APK release data managed by the admin panel.\n// Keep this file JSON-compatible so the Worker can validate and update it.\nexport const FC_MOBILE_27 = '+JSON.stringify(content,null,2)+';\n';
}
function parseFootball(text) {
  const match=text.match(/export const FOOTBALL_CENTRE_CONTENT = ([\s\S]+);\s*$/);
  if(!match) throw new Error('Football Centre data file has an unexpected format.');
  try { return JSON.parse(match[1]); } catch { throw new Error('Football Centre data file is not JSON-compatible.'); }
}

function validateFootball(content) {
  if(!content || typeof content !== 'object' || !content.clubs || !Array.isArray(content.matches) || !content.analysis || !content.totw || !content.settings) throw new Error('Football Centre content is incomplete.');
  for(const [id, club] of Object.entries(content.clubs)) {
    if(!id || !club || !club.name || !club.short || !club.logo) throw new Error('Every club needs an ID, name, short name, and logo URL.');
  }
  const ids=new Set(Object.keys(content.clubs));
  const matchIds=new Set();
  for(const match of content.matches) {
    if(!match?.id || matchIds.has(match.id)) throw new Error('Football Centre match IDs must be unique.');
    if(!Number.isInteger(Number(match.week)) || Number(match.week)<1) throw new Error(`Invalid week for ${match.id}.`);
    if(!ids.has(match.home) || !ids.has(match.away)) throw new Error(`Match ${match.id} references an unknown club.`);
    if(match.home===match.away) throw new Error(`Match ${match.id} cannot use the same club twice.`);
    matchIds.add(match.id);
  }
  const scoring=content.settings.scoring;
  for(const key of ['played','worldClass','correctPrediction']) if(!Number.isFinite(Number(scoring?.[key])) || Number(scoring[key])<0) throw new Error(`Football Centre scoring value "${key}" must be a non-negative number.`);
  if(!content.settings.cycleId) throw new Error('Football Centre cycle ID is required.');
  if(!Number.isFinite(Number(content.settings.startingBalance)) || Number(content.settings.startingBalance)<0) throw new Error('Starting balance must be a non-negative number.');
  if(!content.analysis.videoEmbedUrl || !content.analysis.videoWatchUrl) throw new Error('Analysis video URLs are required.');
  if(Array.isArray(content.analysis.videos)) {
    if(!content.analysis.videos.length) throw new Error('Analysis video archive cannot be empty.');
    for(const [i,v] of content.analysis.videos.entries()) {
      if(!v || !String(v.title||'').trim() || !String(v.embedUrl||'').trim() || !String(v.watchUrl||'').trim()) throw new Error('Analysis video '+(i+1)+' is incomplete.');
      if(!/^https:\/\/www\.youtube(?:-nocookie)?\.com\/embed\/[^/]+/i.test(String(v.embedUrl))) throw new Error('Analysis video '+(i+1)+' must use a YouTube /embed/ URL.');
    }
  }
  if(!content.videoEmbedUrl || !content.videoWatchUrl) { content.videoEmbedUrl=content.analysis.videoEmbedUrl; content.videoWatchUrl=content.analysis.videoWatchUrl; }
}

function parseRankUp(text) {
  const m=text.match(/export const RANKS = (\[[\s\S]*?\]);\s*export const RANK_COSTS = (\[[\s\S]*?\]);/);
  if(!m) throw new Error('Rank Up data file has an unexpected format.');
  const ranks=JSON.parse(m[1]);
  const costs=JSON.parse(m[2].replace(/\bInfinity\b/g,'null'));
  return {ranks,costs};
}
function rankUpText(data) {
  const ranks=data.ranks.map((r,i)=>({value:i,name:String(r.name||'').trim()}));
  const costs=data.costs.map(x=>({min:Number(x.min),max:x.max==='Infinity'||x.max===null?null:Number(x.max),label:String(x.label||'').trim(),costs:x.costs.map(Number)}));
  return `export const RANKS = ${JSON.stringify(ranks,null,2)};

export const RANK_COSTS = ${JSON.stringify(costs,null,2)};

export function getRankBracket(baseOVR) {
  const value = Number(baseOVR);
  if (!Number.isInteger(value) || value < 0) return null;
  return RANK_COSTS.find((item) => value >= item.min && (item.max === null || value <= item.max)) ?? null;
}
`;
}
function validateRankUp(data) {
  if(!data||!Array.isArray(data.ranks)||data.ranks.length!==6||!Array.isArray(data.costs)||!data.costs.length) throw new Error('Rank Up data is incomplete.');
  data.ranks.forEach((r,i)=>{if(!String(r.name||'').trim()) throw new Error(`Rank R${i} needs a name.`);});
  data.costs.forEach((x,i)=>{if(!String(x.label||'').trim()||!Number.isFinite(Number(x.min))||!Array.isArray(x.costs)||x.costs.length!==5) throw new Error(`Rank bracket ${i+1} is incomplete.`);x.costs.forEach(c=>{if(!Number.isFinite(Number(c))||Number(c)<0) throw new Error('Rank Up costs must be non-negative numbers.');});});
}
function parseTraining(text) {
  const levels=text.match(/export const TRAINING_LEVELS = (\[[\s\S]*?\]);/)?.[1]; const fodder=text.match(/export const FODDER = (\[[\s\S]*?\]);/)?.[1];
  if(!levels||!fodder) throw new Error('Training data file has an unexpected format.'); return {levels:JSON.parse(levels),fodder:JSON.parse(fodder)};
}
function trainingText(data) { return `// Training calculator data managed by the admin panel.\nexport const TRAINING_LEVELS = ${JSON.stringify(data.levels,null,2)};\n\nexport const FODDER = ${JSON.stringify(data.fodder,null,2)};\n\nexport const MAX_TRAINING_LEVEL = ${data.levels.length-1};\nexport const TRAINING_TRANSFER_RATE = 0.9;\n`; }
function parseFrontmatter(text) {
  const m=text.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if(!m) return {data:{},body:text};
  const data={};
  for(const line of m[1].split('\n')) {
    const hit=line.match(/^([A-Za-z0-9_]+):\s*(.*)$/);
    if(!hit) continue;
    let value=hit[2].trim();
    if((value.startsWith('"')&&value.endsWith('"'))||(value.startsWith("'")&&value.endsWith("'"))) value=value.slice(1,-1);
    if(value==='true'||value==='false') data[hit[1]]=value==='true';
    else if(value==='null') data[hit[1]]=null;
    else if(/^\d+$/.test(value)) data[hit[1]]=Number(value);
    else if(value.startsWith('[')) { try { data[hit[1]]=JSON.parse(value); } catch { data[hit[1]]=value; } }
    else data[hit[1]]=value;
  }
  return {data,body:m[2]};
}
function yamlValue(value) {
  if(value === null || value === undefined) return 'null';
  if(typeof value === 'boolean' || typeof value === 'number') return String(value);
  if(Array.isArray(value)) return JSON.stringify(value);
  return JSON.stringify(String(value));
}
function articleText(a) {
  const tags=Array.isArray(a.tags)?a.tags:[];
  const jsonArray=(value)=>JSON.stringify(Array.isArray(value)?value:[]);
  const firstInlineImage=String(a.body||'').match(/!\[[^\]]*\]\(([^)]+)\)/)?.[1] || '';
  const effectiveImage=a.image||firstInlineImage;
  return `---
id: ${yamlValue(a.id)}
slug: ${yamlValue(a.slug)}
title: ${yamlValue(a.title)}
subtitle: ${yamlValue(a.subtitle||'')}
description: ${yamlValue(a.description||'')}
type: ${yamlValue(a.type||'guide')}
category: ${yamlValue(a.category||'Guides')}
author: ${yamlValue(a.author||'TanzimFC')}
status: ${yamlValue(a.status||'draft')}
createdBy: ${yamlValue(a.createdBy||a.author||'TanzimFC')}
createdAt: ${yamlValue(a.createdAt||new Date().toISOString())}
updatedAt: ${yamlValue(a.updatedAt||new Date().toISOString())}
publishedAt: ${yamlValue(a.status==='published' ? (a.publishedAt||new Date().toISOString()) : null)}
image: ${yamlValue(effectiveImage)}
imageAlt: ${yamlValue(a.imageAlt||'')}
imageCaption: ${yamlValue(a.imageCaption||'')}
thumbnail: ${yamlValue(a.thumbnail||'')}
excerpt: ${yamlValue(a.excerpt||a.description||'')}
tags: ${jsonArray(tags)}
relatedPlayers: ${jsonArray(a.relatedPlayers)}
relatedEvents: ${jsonArray(a.relatedEvents)}
relatedArticles: ${jsonArray(a.relatedArticles)}
relatedTools: ${jsonArray(a.relatedTools)}
relatedCodes: ${jsonArray(a.relatedCodes)}
featured: ${Boolean(a.featured)}
readingTime: ${Number(a.readingTime)||Math.max(1,Math.ceil(String(a.body||'').split(/\s+/).filter(Boolean).length/220))}
seoTitle: ${yamlValue(a.seoTitle||a.title)}
seoDescription: ${yamlValue(a.seoDescription||a.description||'')}
canonicalUrl: ${yamlValue(a.canonicalUrl||'')}
sources: ${jsonArray(a.sources)}
factStatus: ${yamlValue(a.factStatus||'verified')}
lastReviewed: ${yamlValue(a.lastReviewed||'')}
series: ${yamlValue(a.series||'')}
---

${String(a.body||'').trim()}
`;
}

function validateTraining(data) {
  if(!data||!Array.isArray(data.levels)||data.levels.length<2||!Array.isArray(data.fodder)||!data.fodder.length) throw new Error('Training data is incomplete.');
  data.levels.forEach((v,i)=>{if(!Number.isFinite(Number(v))||Number(v)<0||(i&&Number(v)<Number(data.levels[i-1]))) throw new Error('Training XP levels must be non-negative and ascending.');});
  data.fodder.forEach((x,i)=>{if(!x?.id||!String(x.label||'').trim()||!Number.isFinite(Number(x.xp))||Number(x.xp)<0) throw new Error(`Fodder entry ${i+1} is invalid.`);});
}

async function creatorRecord(request, env) {
  const session=await creatorAuthenticated(request,env);
  if(!session) return null;
  const database=await d1(env);
  return database.prepare('SELECT id, username, display_name, bio, avatar_url, website_url, role, active FROM creators WHERE id=? AND active=1 LIMIT 1').bind(session.id).first();
}
async function d1(env) {
  if (!env.DB) throw new Error('D1 binding DB is not configured in the Worker.');
  return env.DB;
}

function tempPassword() { const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%'; const bytes=crypto.getRandomValues(new Uint8Array(18)); return Array.from(bytes,b=>chars[b%chars.length]).join(''); }

